static int relstop(double vold, double vnew, double reltol, double abstol)
{
    if (std::isinf(vold))
        return 0;
    return (fabs(vnew - vold) < abstol || fabs(vnew - vold) < reltol * (fabs(vnew) + fabs(vold)) * 0.5 || (reltol > 0 && vnew == vold));       /* catch vnew == vold == 0 */
}

