/* LOCAL: NLopt's luksan_plis for unbounded variables with NLopt's default tolerances (see LuksanPLIS.h). */
int LuksanPLIS(int n, LuksanObjective f, void *f_data, double *x, double *minf, double stopval, int maxeval, int mf,
	int *evaluations, int fast)
{
     int i, *ix, nb = 1;
     double *work, *xl, *xu, *xo, *gf, *s, *go, *uo, *vo;
     double gmax, minf_est;
     double xmax = 0; /* no maximum */
     int iest = 0; /* we have no estimate of min function value */
     int mit = 0; /* default no limit on #iterations */
     int mfv = maxeval;
     stat_common stat;
     int iterm;
     double tolg = 0.;
     int nevals = 0;
     nlopt_stopping stopping = {(unsigned) n, stopval, 0., 0., 0., NULL, NULL, &nevals, maxeval};
     nlopt_stopping *stop = &stopping;

     if (evaluations) *evaluations = 0;
     if (n < 1 || mf < 1) return -2; /* NLOPT_INVALID_ARGS; NLopt's default history is not offered */
     ix = (int*) malloc(sizeof(int) * n);
     if (!ix) return -3; /* NLOPT_OUT_OF_MEMORY */
     work = (double*) malloc(sizeof(double) * ((size_t) n * 4 + (size_t) n * mf * 2 + (size_t) MAX2(n,mf)*2));
     if (!work) {
	  free(ix);
	  return -3;
     }

     xl = work; xu = xl + n; gf = xu + n; s = gf + n;
     xo = s + n; go = xo + (size_t) n * mf;
     uo = go + (size_t) n * mf; vo = uo + MAX2(n,mf);

     for (i = 0; i < n; ++i) {
	  ix[i] = 0; /* unbounded */
	  xl[i] = -HUGE_VAL;
	  xu[i] = HUGE_VAL;
     }

     memset(xo, 0, sizeof(double) * (size_t) n * mf);

     plis_(&n, &nb, x, ix, xl, xu,
	   gf, s, xo, go, uo, vo,
	   &xmax,
	   &stop->xtol_rel,
	   &stop->ftol_rel,
	   &stop->minf_max,
	   &tolg,
	   stop,
	   &minf_est, &gmax,
	   minf,
	   &mit, &mfv,
	   &iest,
	   &mf,
	   &iterm, &stat,
	   f, f_data, fast);

     free(work);
     free(ix);
     if (evaluations) *evaluations = nevals;

     switch (iterm) { /* NLopt's nlopt_result values */
	 case 1: return 4; /* NLOPT_XTOL_REACHED */
	 case 2: return 3; /* NLOPT_FTOL_REACHED */
	 case 3: return 2; /* NLOPT_STOPVAL_REACHED */
	 case 4: return 1; /* NLOPT_SUCCESS: gradient tolerance reached */
	 case 6: return 1;
	 case 12: case 13: return 5; /* NLOPT_MAXEVAL_REACHED */
	 default: return -1; /* NLOPT_FAILURE */
     }
}
